export const file = {
  contents:
    `export function greet(name: string = "world") {\n  const greeting = ` +
    "`Welcome, ${name}!`" +
    `;\n  return greeting;\n}\n`,
  name: "greeting.ts",
};

import { useState } from "react";
import {
  FileView,
  FileViewHeader,
  FileViewTitle,
  FileViewActions,
  FileViewContent,
  FileViewCopyButton,
} from "@/registry/erbium/blocks/file-view";
import { Button } from "@/registry/erbium/ui/button";
import { file } from "../examples/file";

const Example = () => {
  const [wrap, setWrap] = useState(false);

  return (
    <FileView
      file={file}
      options={{ overflow: wrap ? "wrap" : "scroll" }}
      className="w-full max-w-4xl"
    >
      <FileViewHeader>
        <FileViewTitle />
        <FileViewActions>
          <Button
            variant="ghost"
            size="xs"
            aria-pressed={wrap}
            onClick={() => {
              setWrap(!wrap);
            }}
          >
            Wrap lines
          </Button>
          <FileViewCopyButton />
        </FileViewActions>
      </FileViewHeader>
      <FileViewContent className="max-h-80" />
    </FileView>
  );
};

export default Example;
